#[test]
fn test_an_apple_vision_answer_is_valid_and_its_words_carry_their_lines_confidence() {
    let c: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let scratch: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let caps: i32 = vision_caps();
    let at: i32 = oil_begin(c, 7, oen_apple_vision(), caps, oc_quad() + oc_lconf(), sg_page_auto(), oil_ck_line(), 1701734144, lg_recognizer());
    crate::testport::assert_eq(caps, 1056992, "the ceiling of the engine table, and what vision.rs declares");
    oil_line(c, at, 10, 20, 100, 30, -1, 2, 1000, -1, 0, 0, 0, 0, 0, 0, 0, 10, 20, 110, 20, 110, 50, 10, 50, 0);
    oil_line(c, at, 10, 60, 80, 30, -1, 1, 500, -1, 0, 0, 0, 0, 0, 0, 0, 10, 60, 90, 60, 90, 90, 10, 90, 0);
    let a: i32 = oil_word(c, at, 10, 20, 40, 30, 0, 1000, 1701734144, 0, -1, 0);
    oil_word_cp(c, at, a, 72);
    oil_word_cp(c, at, a, 105);
    let alt: i32 = oil_walt(c, at, a, 700);
    oil_walt_cp(c, alt, 72);
    oil_walt_cp(c, alt, 108);
    let b: i32 = oil_word(c, at, 60, 20, 40, 30, 0, 1000, 1701734144, 0, -1, 0);
    oil_word_cp(c, at, b, 79);
    oil_word_cp(c, at, b, 75);
    let d: i32 = oil_word(c, at, 10, 60, 80, 30, 1, 500, 1701734144, 0, -1, 0);
    oil_word_cp(c, at, d, 33);
    oil_end(c, at);
    crate::testport::assert_eq(oil_record_check_bitmap(c, at, 200, 200, scratch), 0, "a valid record for its bitmap");
    crate::testport::assert_eq(oil_get(c, at, oh_ck()), 2, "one confidence per line");
    crate::testport::assert_eq(oil_get(c, at, oh_lg()), 2, "an OS recognizer line");
    crate::testport::assert_eq(oil_nlines(c, at), 2, "two lines");
    crate::testport::assert_eq(oil_nwords(c, at), 3, "three words");
    crate::testport::assert_eq(crate::port::cells_at(c, oil_first_word(c, at) + 5), 1000, "a word has its line's confidence");
    crate::testport::assert_eq(oil_native_check(caps, oc_quad() + oc_lconf()), 1, "what it measures is what it declares");
    crate::testport::assert_eq(oil_native_check(caps, oc_wconf()), 0, "it measures no word confidence, and cannot claim one");
}
