    crate::testport::assert_eq(pk_engine_oen(eng_apple_vision()), 3, "answers as engine 3");
    crate::testport::assert_eq(pk_engine_needs(eng_apple_vision()), 0, "needs no pack");
    crate::testport::assert_eq(pk_engine_caps(eng_apple_vision()), vision_caps(), "the bits, named");
    crate::testport::assert_eq(oil_native_check(pk_engine_caps(eng_apple_vision()), oc_wconf()), 0, "no word confidence in the ceiling");
    crate::testport::assert_eq(pk_engine_caps(eng_windows_media_ocr()), 9216, "Windows: deskew wlang");
    crate::testport::assert_eq(pk_engine_needs(eng_windows_media_ocr()), 0, "needs no pack");
